 valid(a);valid(b);const double ca=std::cos(a.angle),sa=std::sin(a.angle),cb=std::cos(b.angle),sb=std::sin(b.angle);
 const V ax{ca,0,sa},az{-sa,0,ca},bx{cb,0,sb},bz{-sb,0,cb},d=b.center-a.center;
 const V axis[]={ax,az,bx,bz};
